/// <summary>
/// claimJournal's request. RangeId (or LocationFrom/LocationTo) blank means the whole journal.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountClaimRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             userId;
    str             deviceId;
    str             rangeId;
    str             locationFrom;
    str             locationTo;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('RangeId')]
public str parmRangeId(str _value = rangeId)
{
    rangeId = _value;
    return rangeId;
}

[DataMemberAttribute('LocationFrom')]
public str parmLocationFrom(str _value = locationFrom)
{
    locationFrom = _value;
    return locationFrom;
}

[DataMemberAttribute('LocationTo')]
public str parmLocationTo(str _value = locationTo)
{
    locationTo = _value;
    return locationTo;
}
